  "not_included": {
    "what": "Discussion detail: the 40-minute debate on launch timing, the brainstorm list of 11 beta-recruitment ideas (3 adopted, reflected above), and two side conversations about hiring.",
    "why": "You asked for decisions and actions in one loadable record; the reasoning narrative does not fit that shape without burying the loadable fields.",
    "where_it_lives": "Full workshop transcript and notes document, referenced in the tracker as attachment 'planning-workshop-notes'. Nothing was deleted; it is summarized here, not lost."
  },
  "coverage_note": "All 3 decisions and all 3 action items from the workshop are included. The omission is discussion detail only, disclosed here rather than silently dropped."
}

{
  "decision": "Backup frequency for the file server",
  "options": [
    {
      "plan": "Continuous sync",
      "monthly_cost_usd": 410,
      "max_data_loss_window": "Minutes",
      "what_it_misses": "Nothing time-based; still vulnerable to synced corruption or deletion propagating before anyone notices."
    },
    {
      "plan": "Hourly backups",
      "monthly_cost_usd": 260,
      "max_data_loss_window": "Up to 1 hour of work",
      "what_it_misses": "Work created and lost inside the same hour; a full morning's incident can still cost the most recent hour."
    },
    {
      "plan": "Daily backups",
      "monthly_cost_usd": 95,
      "max_data_loss_window": "Up to 1 full working day",
      "what_it_misses": "An entire day's work across the team if failure hits just before the nightly run \u2014 the worst case is a busy day's output."
    },
    {
      "plan": "Weekly backups",
      "monthly_cost_usd": 30,
      "max_data_loss_window": "Up to 5 working days",
      "what_it_misses": "A full week of work; only defensible for archives that barely change."
    }
  ],
  "how_to_decide": "Price one hour of the whole team's lost work. If re-creating an hour of lost work costs more than the $150/month step from daily to hourly, hourly is the rational floor. Continuous sync only pays if a single lost hour is catastrophic rather than merely expensive.",
  "note": "Frequency is not the only axis: every option above also needs at least one offline or immutable copy, or a ransomware event takes the backups with the originals. That requirement does not trade off against cost \u2014 it applies at every tier."
}

{
  "weights": {
    "cost": 0.5,
    "capacity": 0.3,
    "distance": 0.2
  },
  "venues": [
    {
      "venue": "A",
      "scores": {
        "cost": 8,
        "capacity": 6,
        "distance": 9
      },
      "weighted_total": 7.6
    },
    {
      "venue": "B",
      "scores": {
        "cost": 6,
        "capacity": 9,
        "distance": 7
      },
      "weighted_total": 7.1
    },
    {
      "venue": "C",
      "scores": {
        "cost": 9,
        "capacity": 5,
        "distance": 5
      },
      "weighted_total": 7.0
    }
  ],
  "reading": "A wins on your weights, but the margin over B is 0.5 points and it is bought with capacity: A scores 6 on the criterion where B scores 9. If attendance grows beyond the current list, A's weakness becomes binding while its cost advantage stays fixed. C is cheapest and never wins, because its distance and capacity scores drag both other criteria down.",
  "sensitivity_note": "If capacity's weight rose from 30% to just over 40% (with cost's weight falling correspondingly), B would take the lead. The ranking is stable only while cost matters more than room to grow \u2014 that judgment is yours, and it is the real decision underneath the arithmetic."
}
